window.TEAP_LISTENING_SETS = window.TEAP_LISTENING_SETS || {};
window.TEAP_LISTENING_SETS[2] = {"p1":[{"id":"L-1A-01","num":1,"part":"1A","situation":"学生が交通案内所でバス定期券について話しています。","turns":[{"speaker":"W","text":"Excuse me, I'd like to renew my student bus pass, please.","audio":"/teap/audio/s2-l-1a-01-t1.mp3"},{"speaker":"M","text":"Of course. Is it the three-month pass again?","audio":"/teap/audio/s2-l-1a-01-t2.mp3"},{"speaker":"W","text":"Actually, this time I'd like the six-month one, if it's cheaper overall.","audio":"/teap/audio/s2-l-1a-01-t3.mp3"},{"speaker":"M","text":"It is. Six months costs 28,000 yen, while two three-month passes would come to 32,000 yen.","audio":"/teap/audio/s2-l-1a-01-t4.mp3"},{"speaker":"W","text":"Then I'll take the six-month pass. Can I pay by card?","audio":"/teap/audio/s2-l-1a-01-t5.mp3"},{"speaker":"M","text":"Yes, cards are fine. I'll need your student ID to check the discount.","audio":"/teap/audio/s2-l-1a-01-t6.mp3"}],"question":"What will the woman buy?","options":["A three-month bus pass","A six-month bus pass","Two three-month bus passes","A one-month bus pass"],"answer":1,"audioQuestion":"/teap/audio/s2-l-1a-01-q.mp3","jaScript":"女：すみません、学生バス定期券を更新したいのですが。\n男：かしこまりました。また3か月定期ですか？\n女：今回は、合計で安くなるなら6か月のものにしたいです。\n男：安くなります。6か月は28,000円で、3か月を2回買うと32,000円になります。\n女：では6か月定期にします。カードで払えますか？\n男：はい、カードで大丈夫です。割引確認のため学生証を拝見します。","evidence":"Then I'll take the six-month pass.","explanation":"6か月定期（28,000円）が3か月×2回（32,000円）より安いと聞き、女性は6か月定期を選んだ。","trapType":"金額の比較で判断が決まる型"},{"id":"L-1A-02","num":2,"part":"1A","situation":"学生がスポーツセンターでテニスコートの予約を変更しています。","turns":[{"speaker":"M","text":"Hi, I booked tennis court two for Saturday at ten, but I'd like to move it to Sunday if possible.","audio":"/teap/audio/s2-l-1a-02-t1.mp3"},{"speaker":"W","text":"Let me check. Sunday at ten is taken, but Sunday at two is free.","audio":"/teap/audio/s2-l-1a-02-t2.mp3"},{"speaker":"M","text":"Two is a bit late. Is Saturday at four still open?","audio":"/teap/audio/s2-l-1a-02-t3.mp3"},{"speaker":"W","text":"Yes, court two is free at four on Saturday. Shall I move your booking to that?","audio":"/teap/audio/s2-l-1a-02-t4.mp3"},{"speaker":"M","text":"Please do. Same court, just the new time.","audio":"/teap/audio/s2-l-1a-02-t5.mp3"},{"speaker":"W","text":"Done. You're booked for Saturday at four, court two.","audio":"/teap/audio/s2-l-1a-02-t6.mp3"}],"question":"When will the man play tennis?","options":["Saturday at ten","Sunday at ten","Sunday at two","Saturday at four"],"answer":3,"audioQuestion":"/teap/audio/s2-l-1a-02-q.mp3","jaScript":"男：こんにちは、土曜10時にテニスコート2を予約したのですが、日曜に変更できますか？\n女：確認します。日曜10時は埋まっていますが、日曜14時なら空いています。\n男：14時は少し遅いです。土曜16時はまだ空いていますか？\n女：はい、土曜16時ならコート2は空いています。そちらに変更しましょうか？\n男：お願いします。同じコートで、時間だけ変更してください。\n女：完了しました。土曜16時、コート2で予約されています。","evidence":"Done. You're booked for Saturday at four, court two.","explanation":"日曜への変更は希望時間が取れず、最終的に土曜16時に変更が確定した。","trapType":"希望→不可→代替案で確定する型"},{"id":"L-1A-03","num":3,"part":"1A","situation":"学生が図書館のカウンターで本の返却について話しています。","turns":[{"speaker":"W","text":"Hi, I'm returning this novel, but I think there may be a problem.","audio":"/teap/audio/s2-l-1a-03-t1.mp3"},{"speaker":"M","text":"Let's see. The system says this copy was borrowed by a Mr. Tanaka, not by you.","audio":"/teap/audio/s2-l-1a-03-t2.mp3"},{"speaker":"W","text":"Oh! Then this must be my friend's copy. We have the same novel for class, and I picked up the wrong one.","audio":"/teap/audio/s2-l-1a-03-t3.mp3"},{"speaker":"M","text":"That explains it. I can accept the return, but the record will be cleared under his name.","audio":"/teap/audio/s2-l-1a-03-t4.mp3"},{"speaker":"W","text":"That's fine. I'll tell him his book is back, and I'll bring mine tomorrow.","audio":"/teap/audio/s2-l-1a-03-t5.mp3"},{"speaker":"M","text":"Please do. Yours is due on Friday, so tomorrow is no problem.","audio":"/teap/audio/s2-l-1a-03-t6.mp3"}],"question":"What will the woman do tomorrow?","options":["Renew her friend's book","Bring her own copy of the novel","Pay a late fee","Borrow another novel"],"answer":1,"audioQuestion":"/teap/audio/s2-l-1a-03-q.mp3","jaScript":"女：こんにちは、この小説を返却しますが、問題があるかもしれません。\n男：見てみましょう。システムでは、この本は田中さんが借りたことになっていて、あなたではありません。\n女：あっ！ではこれは友達の本ですね。授業で同じ小説を使っていて、私が間違えて持ってきたんです。\n男：なるほど。返却は受け付けますが、記録は彼の名前で消えます。\n女：大丈夫です。彼には本が戻ったと伝えて、私の本は明日持ってきます。\n男：お願いします。あなたの本の期限は金曜なので、明日で問題ありません。","evidence":"I'll tell him his book is back, and I'll bring mine tomorrow.","explanation":"持参したのは友人の借りた本だったため、女性は自分の本を明日持ってくると言った。","trapType":"取り違えに気づく型"},{"id":"L-1A-04","num":4,"part":"1A","situation":"2人の学生がプレゼンテーションのスライドについて話しています。","turns":[{"speaker":"M","text":"Our slides are finished, but the professor said the text is too small to read from the back.","audio":"/teap/audio/s2-l-1a-04-t1.mp3"},{"speaker":"W","text":"Then we should increase the font size and cut some words.","audio":"/teap/audio/s2-l-1a-04-t2.mp3"},{"speaker":"M","text":"I can rewrite the bullet points tonight. Can you fix the charts?","audio":"/teap/audio/s2-l-1a-04-t3.mp3"},{"speaker":"W","text":"Sure. The bar chart especially needs bigger labels.","audio":"/teap/audio/s2-l-1a-04-t4.mp3"},{"speaker":"M","text":"Let's meet at the library at nine tomorrow and check everything together.","audio":"/teap/audio/s2-l-1a-04-t5.mp3"},{"speaker":"W","text":"Good idea. The presentation is at one, so the morning is enough.","audio":"/teap/audio/s2-l-1a-04-t6.mp3"}],"question":"What will the man do tonight?","options":["Fix the bar chart","Rewrite the bullet points","Meet at the library","Give the presentation"],"answer":1,"audioQuestion":"/teap/audio/s2-l-1a-04-q.mp3","jaScript":"男：スライドは完成したけど、先生に文字が小さくて後ろから読めないと言われたよ。\n女：じゃあフォントを大きくして、言葉も削らないとね。\n男：箇条書きは今夜書き直すよ。グラフの方は直してくれる？\n女：いいよ。特に棒グラフはラベルを大きくしないと。\n男：明日9時に図書館で会って、全部一緒に確認しよう。\n女：いいね。発表は13時だから、午前中で十分だよ。","evidence":"I can rewrite the bullet points tonight.","explanation":"役割分担で、男性は今夜箇条書きを書き直し、グラフの修正は女性が担当する。","trapType":"分担の取り違えに注意する型"},{"id":"L-1A-05","num":5,"part":"1A","situation":"学生が書店のアルバイト面接の日程を変更しています。","turns":[{"speaker":"W","text":"Hello, this is Sato. I'm calling about my job interview on Thursday.","audio":"/teap/audio/s2-l-1a-05-t1.mp3"},{"speaker":"M","text":"Yes, Ms. Sato, your interview is at three on Thursday.","audio":"/teap/audio/s2-l-1a-05-t2.mp3"},{"speaker":"W","text":"I'm sorry, but I have a class that ends at four that day. Could I come on Friday instead?","audio":"/teap/audio/s2-l-1a-05-t3.mp3"},{"speaker":"M","text":"Friday at three is fine. Or Friday at eleven, if you prefer the morning.","audio":"/teap/audio/s2-l-1a-05-t4.mp3"},{"speaker":"W","text":"Three is better for me. I'll come on Friday at three.","audio":"/teap/audio/s2-l-1a-05-t5.mp3"},{"speaker":"M","text":"All right. Please bring your student ID and your class schedule.","audio":"/teap/audio/s2-l-1a-05-t6.mp3"}],"question":"When will the woman have her interview?","options":["Thursday at three","Thursday at four","Friday at eleven","Friday at three"],"answer":3,"audioQuestion":"/teap/audio/s2-l-1a-05-q.mp3","jaScript":"女：こんにちは、佐藤です。木曜のアルバイト面接についてお電話しました。\n男：はい、佐藤さん、面接は木曜15時です。\n女：すみません、その日は授業が16時まであって。金曜に変更できますか？\n男：金曜15時で大丈夫です。午前がよければ金曜11時でも。\n女：15時の方がいいです。金曜15時に伺います。\n男：かしこまりました。学生証と時間割をお持ちください。","evidence":"Three is better for me. I'll come on Friday at three.","explanation":"木曜は授業と重なるため金曜に変更し、11時と15時の選択肢から15時を選んだ。","trapType":"日程変更と時刻の選択が重なる型"},{"id":"L-1A-06","num":6,"part":"1A","situation":"学生が駅の窓口で団体切符について話しています。","turns":[{"speaker":"M","text":"Excuse me, our class is going on a field trip next week. Are there group discounts for train tickets?","audio":"/teap/audio/s2-l-1a-06-t1.mp3"},{"speaker":"W","text":"Yes, groups of eight or more get fifteen percent off. How many students are going?","audio":"/teap/audio/s2-l-1a-06-t2.mp3"},{"speaker":"M","text":"We're twelve students and one professor.","audio":"/teap/audio/s2-l-1a-06-t3.mp3"},{"speaker":"W","text":"Then the discount applies to everyone, including your professor.","audio":"/teap/audio/s2-l-1a-06-t4.mp3"},{"speaker":"M","text":"Great. Do we need to book in advance?","audio":"/teap/audio/s2-l-1a-06-t5.mp3"},{"speaker":"W","text":"Yes, please apply at least three days before the trip, with a list of names.","audio":"/teap/audio/s2-l-1a-06-t6.mp3"}],"question":"What must the group do to get the discount tickets?","options":["Pay three days early","Apply at least three days before with a list of names","Travel with more than fifteen people","Buy the tickets at the gate"],"answer":1,"audioQuestion":"/teap/audio/s2-l-1a-06-q.mp3","jaScript":"男：すみません、私たちのクラスが来週フィールドトリップに行きます。電車の切符に団体割引はありますか？\n女：はい、8名以上で15％引きです。何名で行かれますか？\n男：学生12名と先生1名です。\n女：では先生を含め全員に割引が適用されます。\n男：よかった。事前に予約が必要ですか？\n女：はい、出発の3日前までに、名簿を添えてお申し込みください。","evidence":"please apply at least three days before the trip, with a list of names","explanation":"割引自体は13名で適用されるが、条件として「3日前までに名簿付きで申し込む」ことが求められた。","trapType":"割引率ではなく手続き条件を問う型"},{"id":"L-1A-07","num":7,"part":"1A","situation":"学生が大学の遺失物窓口で傘について話しています。","turns":[{"speaker":"W","text":"Excuse me, I left my umbrella in the cafeteria yesterday. Has anyone turned one in?","audio":"/teap/audio/s2-l-1a-07-t1.mp3"},{"speaker":"M","text":"We received three umbrellas yesterday. Can you describe yours?","audio":"/teap/audio/s2-l-1a-07-t2.mp3"},{"speaker":"W","text":"It's dark blue with a wooden handle, and it folds into three parts.","audio":"/teap/audio/s2-l-1a-07-t3.mp3"},{"speaker":"M","text":"Hmm, we have a dark blue one, but its handle is plastic. The wooden one we have is black.","audio":"/teap/audio/s2-l-1a-07-t4.mp3"},{"speaker":"W","text":"Then mine hasn't been turned in yet. I'll check again tomorrow.","audio":"/teap/audio/s2-l-1a-07-t5.mp3"},{"speaker":"M","text":"Please do. New items from the cafeteria usually arrive in the morning.","audio":"/teap/audio/s2-l-1a-07-t6.mp3"}],"question":"Why does the woman decide to come back tomorrow?","options":["The office is closing now","Her umbrella has not been turned in yet","She forgot her student ID","The cafeteria is still checking its rooms"],"answer":1,"audioQuestion":"/teap/audio/s2-l-1a-07-q.mp3","jaScript":"女：すみません、昨日食堂に傘を置き忘れました。届いていませんか？\n男：昨日は傘が3本届きました。特徴を教えていただけますか？\n女：濃い青で、持ち手が木製、三つ折りの傘です。\n男：うーん、濃い青はありますが持ち手はプラスチックです。木製のものは黒ですね。\n女：では私のはまだ届いていないんですね。明日また確認に来ます。\n男：お願いします。食堂からの新しい届け物は、だいたい朝に届きます。","evidence":"Then mine hasn't been turned in yet.","explanation":"特徴（濃い青・木製の持ち手）に一致する傘がなかったため、女性は明日再確認することにした。","trapType":"特徴の部分一致に引っかかる型"},{"id":"L-1A-08","num":8,"part":"1A","situation":"学生がケーキ屋でサークルの先輩のためのケーキを注文しています。","turns":[{"speaker":"M","text":"Hi, I'd like to order a birthday cake for this Saturday.","audio":"/teap/audio/s2-l-1a-08-t1.mp3"},{"speaker":"W","text":"Certainly. Our chocolate cake and strawberry cake are both popular.","audio":"/teap/audio/s2-l-1a-08-t2.mp3"},{"speaker":"M","text":"Our senior loves chocolate, but two members cannot eat eggs. Do you have an egg-free cake?","audio":"/teap/audio/s2-l-1a-08-t3.mp3"},{"speaker":"W","text":"Yes, our rice-flour fruit cake has no eggs, and it is our only egg-free option.","audio":"/teap/audio/s2-l-1a-08-t4.mp3"},{"speaker":"M","text":"Then I'll order the fruit cake. Could you write \"Thank you, Captain\" on it?","audio":"/teap/audio/s2-l-1a-08-t5.mp3"},{"speaker":"W","text":"Of course. It will be ready for pick-up at noon on Saturday.","audio":"/teap/audio/s2-l-1a-08-t6.mp3"}],"question":"Which cake will the man order?","options":["The chocolate cake","The strawberry cake","The rice-flour fruit cake","A custom egg-free chocolate cake"],"answer":2,"audioQuestion":"/teap/audio/s2-l-1a-08-q.mp3","jaScript":"男：こんにちは、今週の土曜用にバースデーケーキを注文したいです。\n女：かしこまりました。チョコレートケーキとイチゴケーキが人気です。\n男：先輩はチョコが好きなんですが、メンバーの2人が卵を食べられなくて。卵なしのケーキはありますか？\n女：はい、米粉のフルーツケーキは卵不使用で、卵なしはそれだけです。\n男：ではフルーツケーキを注文します。「Thank you, Captain」と書いてもらえますか？\n女：もちろんです。土曜の正午にお渡しできます。","evidence":"Then I'll order the fruit cake.","explanation":"卵アレルギーのメンバーがいるため、卵不使用の唯一の選択肢である米粉フルーツケーキを注文した。","trapType":"好みより制約が優先される型"},{"id":"L-1A-09","num":9,"part":"1A","situation":"学生が歯科医院に電話して予約を変更しています。","turns":[{"speaker":"W","text":"Hello, this is Yuki Mori. I have an appointment on Monday at ten, but I can't make it.","audio":"/teap/audio/s2-l-1a-09-t1.mp3"},{"speaker":"M","text":"I'm sorry to hear that. Would you like to reschedule?","audio":"/teap/audio/s2-l-1a-09-t2.mp3"},{"speaker":"W","text":"Yes. Is there anything on Tuesday afternoon?","audio":"/teap/audio/s2-l-1a-09-t3.mp3"},{"speaker":"M","text":"Tuesday is fully booked. The earliest opening is Wednesday at two thirty.","audio":"/teap/audio/s2-l-1a-09-t4.mp3"},{"speaker":"W","text":"Wednesday at two thirty works. Please move my appointment to then.","audio":"/teap/audio/s2-l-1a-09-t5.mp3"},{"speaker":"M","text":"Done. We'll send a reminder message on Tuesday.","audio":"/teap/audio/s2-l-1a-09-t6.mp3"}],"question":"When is the woman's new appointment?","options":["Monday at ten","Tuesday afternoon","Wednesday at two thirty","Tuesday at two thirty"],"answer":2,"audioQuestion":"/teap/audio/s2-l-1a-09-q.mp3","jaScript":"女：こんにちは、森ゆきです。月曜10時に予約があるのですが、行けなくなりました。\n男：それは残念です。変更されますか？\n女：はい。火曜の午後は空いていますか？\n男：火曜は満席です。一番早い空きは水曜14時30分です。\n女：水曜14時30分で大丈夫です。予約をそちらに移してください。\n男：完了しました。火曜にリマインダーメッセージをお送りします。","evidence":"The earliest opening is Wednesday at two thirty.","explanation":"火曜は満席で、最も早い空き枠の水曜14時30分に変更が確定した。リマインダーが火曜に届く点と混同しないこと。","trapType":"希望日が満席で翌日に確定する型"},{"id":"L-1A-10","num":10,"part":"1A","situation":"学生が先輩に家庭教師のアルバイトについて聞いています。","turns":[{"speaker":"M","text":"Senpai, I heard you are quitting your tutoring job. Are they looking for a replacement?","audio":"/teap/audio/s2-l-1a-10-t1.mp3"},{"speaker":"W","text":"Yes, the family wants a new tutor for their son from next month. He is in his second year of junior high school.","audio":"/teap/audio/s2-l-1a-10-t2.mp3"},{"speaker":"M","text":"Which subjects?","audio":"/teap/audio/s2-l-1a-10-t3.mp3"},{"speaker":"W","text":"Mainly English and math, twice a week, on weekday evenings.","audio":"/teap/audio/s2-l-1a-10-t4.mp3"},{"speaker":"M","text":"I'm free on Tuesdays and Thursdays. Could you introduce me to the family?","audio":"/teap/audio/s2-l-1a-10-t5.mp3"},{"speaker":"W","text":"Sure. I'll send them your name tonight, and they'll contact you for a trial lesson.","audio":"/teap/audio/s2-l-1a-10-t6.mp3"}],"question":"What will the woman do tonight?","options":["Give a trial lesson","Send the man's name to the family","Teach English and math","Quit her tutoring job"],"answer":1,"audioQuestion":"/teap/audio/s2-l-1a-10-q.mp3","jaScript":"男：先輩、家庭教師のバイトを辞めると聞きました。後任は探しているんですか？\n女：うん、そのご家庭は来月から新しい先生を探していて。息子さんは中学2年生。\n男：科目は何ですか？\n女：主に英語と数学で、週2回、平日の夜。\n男：僕は火曜と木曜が空いています。そのご家庭に紹介してもらえますか？\n女：いいよ。今夜あなたの名前を送っておくね。体験授業の連絡が来ると思う。","evidence":"I'll send them your name tonight","explanation":"先輩は今夜、男性の名前をご家庭に送ると約束した。体験授業はその後の流れ。","trapType":"今夜の行動と将来の流れを区別する型"},{"id":"L-1B-11","num":11,"part":"1B","situation":"大学図書館からのお知らせを聞いています。","turns":[{"speaker":"M","text":"Attention, please. During the exam period, from January 20th to February 3rd, the central library will extend its opening hours. The library will open at eight in the morning and close at eleven at night, including weekends. Group study rooms can be reserved for up to three hours, one hour longer than usual. However, the fourth-floor reading room will be closed for repairs during the first week. Food is not allowed anywhere in the library, but covered drinks are permitted at the desks on the first and second floors. Please remember to bring your student ID, as entry checks will be stricter during this period.","audio":"/teap/audio/s2-l-1b-11-t1.mp3"}],"question":"What is true about the library during the exam period?","options":["It will close earlier than usual","Group rooms can be used for up to three hours","The fourth floor will be open all period","Drinks are banned everywhere"],"answer":1,"audioQuestion":"/teap/audio/s2-l-1b-11-q.mp3","jaScript":"男：お知らせします。試験期間中の1月20日から2月3日まで、中央図書館は開館時間を延長します。午前8時開館、午後11時閉館で、週末も同様です。グループ学習室は通常より1時間長い最大3時間まで予約できます。ただし4階の閲覧室は初週、修理のため閉鎖されます。館内は飲食禁止ですが、ふた付きの飲み物は1階と2階の机でのみ許可されます。この期間は入館チェックが厳しくなりますので、学生証を忘れずにお持ちください。","evidence":"Group study rooms can be reserved for up to three hours","explanation":"グループ学習室は通常より1時間長い最大3時間まで予約可能。4階は初週閉鎖、飲み物は一部許可であり、選択肢の言い換えに注意。","trapType":"NOT型に近い正誤判定"},{"id":"L-1B-12","num":12,"part":"1B","situation":"潮の満ち引きについての短い講義を聞いています。","turns":[{"speaker":"W","text":"Today, let's look at why the sea rises and falls twice a day. The main cause of the tides is the gravity of the moon. The moon pulls the ocean water toward it, creating a bulge on the side of the Earth facing the moon. At the same time, another bulge forms on the opposite side. As the Earth rotates, coastal areas pass through these bulges, and that is when high tide occurs. The sun also affects the tides, but because it is much farther away, its effect is only about half that of the moon. When the sun and moon line up, their combined pull produces especially high and low tides, called spring tides.","audio":"/teap/audio/s2-l-1b-12-t1.mp3"}],"question":"According to the talk, what is the main cause of the tides?","options":["The rotation of the Earth","The gravity of the sun","The gravity of the moon","The movement of ocean currents"],"answer":2,"audioQuestion":"/teap/audio/s2-l-1b-12-q.mp3","jaScript":"女：今日は、なぜ海が1日に2回満ち引きするのかを見てみましょう。潮の主な原因は月の引力です。月が海水を自分の方へ引くため、月に面した側の地球に水のふくらみができます。同時に、反対側にももう一つのふくらみができます。地球が自転するにつれて沿岸部がこのふくらみを通過し、そのときに満潮になります。太陽も潮に影響しますが、はるかに遠いため、その影響は月の約半分しかありません。太陽と月が一直線に並ぶと、引力が合わさって特に高低の大きい潮、大潮が生じます。","evidence":"The main cause of the tides is the gravity of the moon.","explanation":"本文の冒頭で主因は月の引力と明言されている。太陽の影響は月の約半分。","trapType":"主因と副因の区別"},{"id":"L-1B-13","num":13,"part":"1B","situation":"環境経済学の授業紹介を聞いています。","turns":[{"speaker":"M","text":"Welcome to Environmental Economics. In this course, we study how economic activity affects the natural environment, and how policy can reduce that damage. In the first half of the term, we will analyze problems such as air pollution and waste using basic economic models. In the second half, each group will choose a real city and design an environmental policy for it, such as a plastic-bag charge or a congestion fee for cars. There is no final exam in this course. Instead, your grade will be based on two short reports and the group presentation in the final week. Students who took basic microeconomics will find the course easier, but it is not a requirement.","audio":"/teap/audio/s2-l-1b-13-t1.mp3"}],"question":"How will students be graded in this course?","options":["By a final exam and a group presentation","By two reports and a group presentation","By weekly quizzes and a final report","By a final exam only"],"answer":1,"audioQuestion":"/teap/audio/s2-l-1b-13-q.mp3","jaScript":"男：環境経済学へようこそ。この授業では、経済活動が自然環境にどう影響するか、そして政策がそのダメージをどう減らせるかを学びます。前半は大気汚染や廃棄物などの問題を基本的な経済モデルで分析します。後半はグループごとに実在の都市を1つ選び、レジ袋課金や自動車の渋滞料金といった環境政策を設計します。この授業に期末試験はありません。代わりに、成績は短いレポート2本と最終週のグループ発表で決まります。ミクロ経済学の基礎を履修済みだと理解しやすいですが、必須ではありません。","evidence":"your grade will be based on two short reports and the group presentation","explanation":"期末試験はなく、成績はレポート2本とグループ発表で決まる。","trapType":"評価方法の言い換え"},{"id":"L-1B-14","num":14,"part":"1B","situation":"大学プールからのお知らせを聞いています。","turns":[{"speaker":"W","text":"This is an announcement from the university swimming pool. The pool will be closed from Monday, March 10th, to Friday, March 14th, for annual maintenance of the water filtration system. During this period, swimming lessons and club practices are all cancelled. Members who have a monthly pass will receive a five-day extension automatically, so there is no need to apply at the front desk. The gym and the training room in the same building will remain open as usual. The pool will reopen on Saturday, March 15th, at nine in the morning. We apologize for the inconvenience and thank you for your understanding.","audio":"/teap/audio/s2-l-1b-14-t1.mp3"}],"question":"What should monthly pass holders do about the closure?","options":["Apply at the front desk for an extension","Nothing, because the extension is automatic","Join the gym instead","Come back on March 14th"],"answer":1,"audioQuestion":"/teap/audio/s2-l-1b-14-q.mp3","jaScript":"女：大学プールからのお知らせです。3月10日（月）から3月14日（金）まで、水のろ過システムの年次メンテナンスのためプールを閉鎖します。この期間、水泳レッスンとクラブの練習はすべて中止です。月間パスをお持ちの方は、5日間の延長が自動的に適用されますので、フロントでの申請は不要です。同じ建物内のジムとトレーニング室は通常通り開いています。プールは3月15日（土）午前9時に再開します。ご不便をおかけしますが、ご理解のほどお願いいたします。","evidence":"will receive a five-day extension automatically, so there is no need to apply","explanation":"月間パスの延長は自動適用で申請不要。再開は3月15日（土）。","trapType":"「申請不要」の聞き取り"},{"id":"L-1B-15","num":15,"part":"1B","situation":"自転車の歴史についての短い講義を聞いています。","turns":[{"speaker":"M","text":"The bicycle we know today took almost seventy years to develop. The earliest version, built in Germany in 1817, had two wooden wheels but no pedals; riders pushed the ground with their feet. Pedals were added in the 1860s in France, attached directly to the huge front wheel. Those machines were fast but dangerous, because riders sat very high. The breakthrough came in the 1880s in England, when the chain-driven design appeared, with two wheels of equal size. This 'safety bicycle' is the direct ancestor of the modern bicycle. Within ten years, it had spread across Europe and America, and for the first time, ordinary people could travel freely on their own.","audio":"/teap/audio/s2-l-1b-15-t1.mp3"}],"question":"What was special about the safety bicycle of the 1880s?","options":["It had a huge front wheel","It had no pedals","It used a chain and two equal wheels","It was made of wood"],"answer":2,"audioQuestion":"/teap/audio/s2-l-1b-15-q.mp3","jaScript":"男：今日の自転車の形ができるまで、ほぼ70年かかりました。最古の形は1817年にドイツで作られ、木の車輪が2つあるだけでペダルはなく、乗り手は足で地面を蹴っていました。ペダルは1860年代にフランスで付けられましたが、巨大な前輪に直結していました。あれは速いものの、乗り手の位置がとても高く危険でした。転機は1880年代のイギリスで、チェーン駆動の設計が登場し、車輪は同じ大きさになりました。この「安全型自転車」が現代の自転車の直接の祖先です。10年以内にヨーロッパとアメリカに広がり、普通の人々が初めて自分の力で自由に移動できるようになりました。","evidence":"the chain-driven design appeared, with two wheels of equal size. This 'safety bicycle'","explanation":"1880年代の安全型はチェーン駆動＋同じ大きさの車輪。巨大な前輪やペダルなしはそれ以前の形。","trapType":"時代ごとの特徴の混同"},{"id":"L-1B-16","num":16,"part":"1B","situation":"博物館の特別展についての案内を聞いています。","turns":[{"speaker":"W","text":"Our new special exhibition, 'Daily Life in Ancient Egypt,' opens this Saturday and runs for three months. Most exhibitions focus on kings and temples, but this one shows how ordinary people lived: their bread ovens, children's toys, makeup tools, and even letters written to family members. The most popular item so far is a wooden toy horse that is over three thousand years old. Audio guides are available in four languages, and on Sundays, our staff will demonstrate ancient bread-making in the exhibition hall. Tickets are free for high school students and younger, but the Sunday demonstrations require a separate reservation because space is limited.","audio":"/teap/audio/s2-l-1b-16-t1.mp3"}],"question":"What is special about this exhibition?","options":["It displays the treasures of Egyptian kings","It focuses on the lives of ordinary people","It is open for only one month","Audio guides are available in ten languages"],"answer":1,"audioQuestion":"/teap/audio/s2-l-1b-16-q.mp3","jaScript":"女：新しい特別展「古代エジプトの日常生活」は今週の土曜に開幕し、3か月間開催されます。多くの展覧会は王や神殿に焦点を当てますが、本展は普通の人々の暮らしを紹介します。パン焼き窯、子どものおもちゃ、化粧道具、さらには家族への手紙まで展示します。今のところ一番人気は、3000年以上前の木製の馬のおもちゃです。音声ガイドは4か国語対応で、日曜にはスタッフが展示室で古代のパンの作り方を実演します。高校生以下は入場無料ですが、日曜の実演はスペースの都合で別途予約が必要です。","evidence":"this one shows how ordinary people lived","explanation":"王や神殿ではなく庶民の生活に焦点を当てた点が本展の特徴。","trapType":"対比で特徴を示す型"},{"id":"L-1B-17","num":17,"part":"1B","situation":"天気予報の作り方についての短い講義を聞いています。","turns":[{"speaker":"M","text":"How do forecasters predict tomorrow's weather? The process begins with observation. Thousands of stations on land, ships at sea, and satellites in space measure temperature, pressure, and wind every few minutes. All this data is sent to powerful computers, which run mathematical models of the atmosphere. The computers divide the air into millions of small boxes and calculate how conditions in each box will change. Forecasters then check the computer results and adjust them using local knowledge. A modern three-day forecast is now as accurate as a one-day forecast was thirty years ago, mainly because satellites provide data from oceans, where ground stations cannot exist.","audio":"/teap/audio/s2-l-1b-17-t1.mp3"}],"question":"Why have weather forecasts become more accurate?","options":["Because forecasters no longer use computers","Because satellites provide data from the oceans","Because the atmosphere has become simpler","Because ships measure the wind every hour"],"answer":1,"audioQuestion":"/teap/audio/s2-l-1b-17-q.mp3","jaScript":"男：予報士はどうやって明日の天気を予測するのでしょうか。プロセスは観測から始まります。陸上の何千もの観測所、海上の船舶、宇宙の衛星が、数分ごとに気温・気圧・風を測定します。これらのデータは強力なコンピュータに送られ、大気の数学モデルを動かします。コンピュータは空気を何百万もの小さな箱に分け、それぞれの状態がどう変化するかを計算します。その後、予報士が計算結果を確認し、地域の知識で調整します。現代の3日予報は、30年前の1日予報と同じくらい正確になりました。主な理由は、地上観測所を置けない海上のデータを衛星が提供してくれるからです。","evidence":"mainly because satellites provide data from oceans, where ground stations cannot exist","explanation":"精度向上の主因は、観測所のない海上のデータを衛星が補うことだと明言されている。","trapType":"理由を直接問う型"},{"id":"L-1B-18","num":18,"part":"1B","situation":"キャリアセンターのワークショップの案内を聞いています。","turns":[{"speaker":"W","text":"The Career Center will hold a resume-writing workshop next Wednesday at four in the afternoon, in Lecture Room B. This workshop is designed for third-year students who are starting their job search, but first- and second-year students are also welcome. Participants will learn how to describe their part-time jobs and club activities in a way that appeals to employers. Please bring a draft of your resume if you have one; if not, worksheets will be provided. The workshop is limited to forty students, and registration closes on Monday. Last year, the seats filled within two days, so early registration is recommended.","audio":"/teap/audio/s2-l-1b-18-t1.mp3"}],"question":"Why does the speaker recommend early registration?","options":["The workshop is only for third-year students","Registration closes on Wednesday","The seats filled quickly last year","Participants must bring a resume draft"],"answer":2,"audioQuestion":"/teap/audio/s2-l-1b-18-q.mp3","jaScript":"女：キャリアセンターは来週の水曜午後4時から、B講義室で履歴書作成ワークショップを開催します。就職活動を始める3年生向けですが、1・2年生も歓迎です。アルバイトやサークル活動を、企業に響く形でどう書くかを学びます。履歴書の下書きがあればお持ちください。なければワークシートを用意します。定員は40名で、申込は月曜に締め切ります。昨年は2日で満席になりましたので、早めの申込をおすすめします。","evidence":"Last year, the seats filled within two days, so early registration is recommended.","explanation":"早めの申込を勧める理由は、昨年2日で満席になったこと。申込締切は月曜。","trapType":"理由と締切日の混同"},{"id":"L-1B-19","num":19,"part":"1B","situation":"サンゴ礁についての短い講義を聞いています。","turns":[{"speaker":"M","text":"Coral reefs cover less than one percent of the ocean floor, yet they are home to about a quarter of all marine species. This is possible because corals build complex structures that provide shelter and food. However, corals live in a delicate partnership with tiny algae inside their bodies. When the sea becomes too warm, the corals push the algae out and turn white, a process called bleaching. Without the algae, corals slowly starve. Brief bleaching is survivable, but in recent decades, warm periods have become longer and more frequent. In some regions, half of the shallow-water corals have died since the 1990s.","audio":"/teap/audio/s2-l-1b-19-t1.mp3"}],"question":"What happens when corals bleach?","options":["They grow faster than usual","They lose the algae living inside them","They move to deeper water","They attract more fish species"],"answer":1,"audioQuestion":"/teap/audio/s2-l-1b-19-q.mp3","jaScript":"男：サンゴ礁は海底の1％未満しか占めていませんが、全海洋生物の約4分の1の住処です。これは、サンゴが隠れ場所と食料を提供する複雑な構造を作るからです。しかしサンゴは、体内の小さな藻類との繊細な共生で生きています。海水が温かくなりすぎると、サンゴは藻類を追い出して白くなります。これが白化です。藻類を失うと、サンゴはゆっくり飢えていきます。短期間の白化なら回復できますが、近年は温暖な期間が長く頻繁になっています。地域によっては、1990年代以降に浅瀬のサンゴの半分が死んでしまいました。","evidence":"the corals push the algae out and turn white, a process called bleaching","explanation":"白化とは、サンゴが体内の藻類を追い出して白くなる現象。","trapType":"用語の定義を問う型"},{"id":"L-1B-20","num":20,"part":"1B","situation":"天文学入門の授業紹介を聞いています。","turns":[{"speaker":"W","text":"This is an introduction to Introduction to Astronomy, a course for students with no science background. We will not use advanced mathematics; instead, we will build understanding through observation. Twice during the term, we will visit the university observatory in the evening to observe the moon and planets through the large telescope. The main topics are the solar system, the life of stars, and the search for planets around other stars. Your grade will come from a midterm quiz, a short observation report, and a final group project in which you design a poster about an astronomical object of your choice. Please note that the evening sessions are required, not optional.","audio":"/teap/audio/s2-l-1b-20-t1.mp3"}],"question":"What are students required to do in this course?","options":["Use advanced mathematics","Attend the evening observatory sessions","Buy their own telescope","Write a report every week"],"answer":1,"audioQuestion":"/teap/audio/s2-l-1b-20-q.mp3","jaScript":"女：こちらは天文学入門の紹介です。理系の背景がない学生向けの授業です。高度な数学は使いません。代わりに観察を通して理解を深めます。学期中に2回、夜に大学の天文台を訪れ、大型望遠鏡で月や惑星を観察します。主なテーマは太陽系、星の生涯、そして他の星の周りの惑星探しです。成績は中間の小テスト、短い観察レポート、そして好きな天体についてポスターを作る最終グループプロジェクトで決まります。なお、夜の観察セッションは任意ではなく必須ですのでご注意ください。","evidence":"the evening sessions are required, not optional","explanation":"夜の天文台セッションは必須。高度な数学は使わないと明言されている。","trapType":"「必須」と「任意」の聞き分け"},{"id":"L-1C-21","num":21,"part":"1C","situation":"学生課の担当者がサークルの加入者数について話しています。グラフを見ながら聞いてください。","turns":[{"speaker":"W","text":"Let me share this year's club membership numbers. Sports clubs are the largest group, with 120 members. Music clubs come next, with 80 members. Volunteer clubs have 60 members, and art clubs are the smallest, with 50 members. Compared with last year, sports and volunteer clubs grew, while art clubs stayed almost the same.","audio":"/teap/audio/s2-l-1c-21-t1.mp3"}],"question":"Which chart correctly shows the club membership numbers?","options":["Chart A","Chart B","Chart C","Chart D"],"chartOptions":[{"type":"bar","title":"Club Members","unit":"members","max":140,"items":[{"label":"Sports","value":120},{"label":"Music","value":80},{"label":"Art","value":50},{"label":"Volunteer","value":60}]},{"type":"bar","title":"Club Members","unit":"members","max":140,"items":[{"label":"Sports","value":120},{"label":"Music","value":80},{"label":"Art","value":60},{"label":"Volunteer","value":50}]},{"type":"bar","title":"Club Members","unit":"members","max":140,"items":[{"label":"Sports","value":80},{"label":"Music","value":120},{"label":"Art","value":50},{"label":"Volunteer","value":60}]},{"type":"bar","title":"Club Members","unit":"members","max":140,"items":[{"label":"Sports","value":120},{"label":"Music","value":60},{"label":"Art","value":50},{"label":"Volunteer","value":80}]}],"answer":0,"jaScript":"女：今年のサークル加入者数をお伝えします。スポーツ系が最大で120名。次が音楽系で80名。ボランティア系は60名で、美術系が最小の50名です。昨年と比べると、スポーツとボランティアは増え、美術はほぼ変わりませんでした。","evidence":"Sports clubs are the largest group, with 120 members. Music clubs come next, with 80 members. Volunteer clubs have 60 members, and art clubs are the smallest, with 50 members.","explanation":"正解は Chart A（Sports 120 / Music 80 / Art 50 / Volunteer 60）。他のグラフは1組ずつ値が入れ替わっている。","trapType":"数値の入れ替え型グラフ"},{"id":"L-1C-22","num":22,"part":"1C","situation":"気象クラブの学生が月ごとの降水量について話しています。グラフを見ながら聞いてください。","turns":[{"speaker":"M","text":"Our weather club recorded the rainfall in the city this year. April had 90 millimeters of rain. June was the wettest month we measured, with 160 millimeters, because of the rainy season. In August, rainfall dropped to 110 millimeters, and by October it had fallen further to 70 millimeters, the driest of the four months.","audio":"/teap/audio/s2-l-1c-22-t1.mp3"}],"question":"Which chart correctly shows the rainfall?","options":["Chart A","Chart B","Chart C","Chart D"],"chartOptions":[{"type":"line","title":"Rainfall","unit":"mm","max":200,"labels":["Apr","Jun","Aug","Oct"],"values":[90,110,160,70]},{"type":"line","title":"Rainfall","unit":"mm","max":200,"labels":["Apr","Jun","Aug","Oct"],"values":[160,90,110,70]},{"type":"line","title":"Rainfall","unit":"mm","max":200,"labels":["Apr","Jun","Aug","Oct"],"values":[90,160,110,70]},{"type":"line","title":"Rainfall","unit":"mm","max":200,"labels":["Apr","Jun","Aug","Oct"],"values":[90,160,70,110]}],"answer":2,"jaScript":"男：私たちの気象クラブは、今年の市の降水量を記録しました。4月は90ミリ。6月は梅雨のため、測定した中で最も多い160ミリでした。8月には110ミリまで減り、10月にはさらに70ミリまで下がって、4か月で最も少なくなりました。","evidence":"April had 90 millimeters of rain. June was the wettest month we measured, with 160 millimeters","explanation":"正解は Chart C（Apr 90 / Jun 160 / Aug 110 / Oct 70）。","trapType":"数値の入れ替え型グラフ"},{"id":"L-1C-23","num":23,"part":"1C","situation":"大学の広報担当者が新入生アンケートの結果について話しています。グラフを見ながら聞いてください。","turns":[{"speaker":"W","text":"We asked new students why they chose this university. The most common reason, at 35 percent, was that it is close to their home. Thirty percent chose the university's reputation. Twenty percent mentioned reasonable tuition, and the remaining 15 percent said their friends were coming here too.","audio":"/teap/audio/s2-l-1c-23-t1.mp3"}],"question":"Which chart correctly shows the survey results?","options":["Chart A","Chart B","Chart C","Chart D"],"chartOptions":[{"type":"bar","title":"Why Students Chose This University","unit":"%","max":40,"items":[{"label":"Close to Home","value":30},{"label":"Reputation","value":35},{"label":"Tuition","value":20},{"label":"Friends","value":15}]},{"type":"bar","title":"Why Students Chose This University","unit":"%","max":40,"items":[{"label":"Close to Home","value":35},{"label":"Reputation","value":30},{"label":"Tuition","value":20},{"label":"Friends","value":15}]},{"type":"bar","title":"Why Students Chose This University","unit":"%","max":40,"items":[{"label":"Close to Home","value":35},{"label":"Reputation","value":30},{"label":"Tuition","value":15},{"label":"Friends","value":20}]},{"type":"bar","title":"Why Students Chose This University","unit":"%","max":40,"items":[{"label":"Close to Home","value":35},{"label":"Reputation","value":20},{"label":"Tuition","value":30},{"label":"Friends","value":15}]}],"answer":1,"jaScript":"女：新入生に、この大学を選んだ理由を聞きました。最も多かった理由は35％で「家から近い」でした。30％が大学の評判を選びました。20％が学費の手頃さを挙げ、残りの15％は友達も来るからと答えました。","evidence":"The most common reason, at 35 percent, was that it is close to their home. Thirty percent chose the university's reputation.","explanation":"正解は Chart B（Close to Home 35 / Reputation 30 / Tuition 20 / Friends 15、合計100％）。","trapType":"数値の入れ替え型グラフ"},{"id":"L-1C-24","num":24,"part":"1C","situation":"大学ジムのマネージャーが時間帯別の利用者数について話しています。グラフを見ながら聞いてください。","turns":[{"speaker":"M","text":"Here are the average visitor numbers for the university gym. At seven in the morning, we usually have about 40 visitors. At noon, the number drops to 25, our quietest time. The gym gets busiest at five in the evening, with about 90 visitors. By nine at night, the number falls to 55.","audio":"/teap/audio/s2-l-1c-24-t1.mp3"}],"question":"Which chart correctly shows the gym visitor numbers?","options":["Chart A","Chart B","Chart C","Chart D"],"chartOptions":[{"type":"line","title":"Gym Visitors","unit":"visitors","max":100,"labels":["7 AM","12 PM","5 PM","9 PM"],"values":[40,90,25,55]},{"type":"line","title":"Gym Visitors","unit":"visitors","max":100,"labels":["7 AM","12 PM","5 PM","9 PM"],"values":[25,40,90,55]},{"type":"line","title":"Gym Visitors","unit":"visitors","max":100,"labels":["7 AM","12 PM","5 PM","9 PM"],"values":[40,25,55,90]},{"type":"line","title":"Gym Visitors","unit":"visitors","max":100,"labels":["7 AM","12 PM","5 PM","9 PM"],"values":[40,25,90,55]}],"answer":3,"jaScript":"男：大学ジムの平均利用者数です。朝7時はだいたい40人。正午は25人まで下がって、一番空いている時間です。最も混むのは夕方5時で約90人。夜9時には55人まで減ります。","evidence":"The gym gets busiest at five in the evening, with about 90 visitors.","explanation":"正解は Chart D（7 AM 40 / 12 PM 25 / 5 PM 90 / 9 PM 55）。","trapType":"数値の入れ替え型グラフ"},{"id":"L-1C-25","num":25,"part":"1C","situation":"寮の管理人がリサイクル率について話しています。グラフを見ながら聞いてください。","turns":[{"speaker":"W","text":"This year's recycling results for the four dormitories are ready. Dorm B did best, recycling 80 percent of its waste. Dorm D followed with 70 percent. Dorm A recycled 65 percent, and Dorm C had the lowest rate, at 55 percent. Next year, we hope Dorm C can reach at least 65 percent.","audio":"/teap/audio/s2-l-1c-25-t1.mp3"}],"question":"Which chart correctly shows the recycling rates?","options":["Chart A","Chart B","Chart C","Chart D"],"chartOptions":[{"type":"bar","title":"Recycling Rate by Dormitory","unit":"%","max":100,"items":[{"label":"Dorm A","value":65},{"label":"Dorm B","value":80},{"label":"Dorm C","value":55},{"label":"Dorm D","value":70}]},{"type":"bar","title":"Recycling Rate by Dormitory","unit":"%","max":100,"items":[{"label":"Dorm A","value":80},{"label":"Dorm B","value":65},{"label":"Dorm C","value":55},{"label":"Dorm D","value":70}]},{"type":"bar","title":"Recycling Rate by Dormitory","unit":"%","max":100,"items":[{"label":"Dorm A","value":65},{"label":"Dorm B","value":80},{"label":"Dorm C","value":70},{"label":"Dorm D","value":55}]},{"type":"bar","title":"Recycling Rate by Dormitory","unit":"%","max":100,"items":[{"label":"Dorm A","value":55},{"label":"Dorm B","value":80},{"label":"Dorm C","value":65},{"label":"Dorm D","value":70}]}],"answer":0,"jaScript":"女：今年の4つの寮のリサイクル結果が出ました。B寮が最も良く、ごみの80％をリサイクルしました。次がD寮で70％。A寮は65％で、C寮が最も低い55％でした。来年はC寮が少なくとも65％に届くことを期待しています。","evidence":"Dorm B did best, recycling 80 percent of its waste. Dorm D followed with 70 percent.","explanation":"正解は Chart A（A 65 / B 80 / C 55 / D 70）。","trapType":"数値の入れ替え型グラフ"}],"p2":[{"setId":"L-2A-SET1","part":"2A","title":"Set 1: Planning a Welcome Party for Exchange Students","situation":"学生と国際交流サークルの代表が、留学生の歓迎会について話しています。","turns":[{"speaker":"W","text":"Thanks for meeting me. We're planning the welcome party for the new exchange students, and I'd like to confirm the main points with you.","audio":"/teap/audio/s2-l-2a-set1-t1.mp3"},{"speaker":"M","text":"Of course. First, the date. The exchange students arrive on the 5th, so how about holding the party on the evening of the 8th? That gives them a few days to settle in.","audio":"/teap/audio/s2-l-2a-set1-t2.mp3"},{"speaker":"W","text":"The 8th sounds good. Last year we used the student hall, but it felt too big for forty people. Could we use the international lounge instead? It holds about fifty.","audio":"/teap/audio/s2-l-2a-set1-t3.mp3"},{"speaker":"M","text":"The lounge is better, I agree. I'll book it this afternoon. Now, about food — last year we ordered pizza, but several students couldn't eat it for religious reasons.","audio":"/teap/audio/s2-l-2a-set1-t4.mp3"},{"speaker":"W","text":"This year, let's prepare a buffet with clear labels on every dish, including vegetarian and halal options. The cafeteria can do that if we order a week ahead.","audio":"/teap/audio/s2-l-2a-set1-t5.mp3"},{"speaker":"M","text":"Good. Then I'll place the order by the 1st. What about activities? The quiz game about Japan was popular last year.","audio":"/teap/audio/s2-l-2a-set1-t6.mp3"},{"speaker":"W","text":"Let's do the quiz again, but in mixed teams this time, so the exchange students talk with Japanese students from the start.","audio":"/teap/audio/s2-l-2a-set1-t7.mp3"},{"speaker":"M","text":"Great idea. One more thing: we need two students to give short speeches. Would you be one of them?","audio":"/teap/audio/s2-l-2a-set1-t8.mp3"},{"speaker":"W","text":"I'd be happy to. And I'll ask Kenji to give the other speech — he studied abroad last year, so he knows how the new students feel.","audio":"/teap/audio/s2-l-2a-set1-t9.mp3"},{"speaker":"M","text":"Perfect. So: party on the 8th in the international lounge, buffet ordered by the 1st, mixed-team quiz, and speeches by you and Kenji. Let me send a summary to all the members tonight.","audio":"/teap/audio/s2-l-2a-set1-t10.mp3"}],"jaScript":"女：お時間ありがとうございます。新入留学生の歓迎会を計画していて、要点を確認したいです。\n男：もちろんです。まず日程。留学生は5日に到着するので、パーティーは8日の夜はどうでしょう。落ち着くまで数日あります。\n女：8日でいいと思います。昨年は学生ホールを使いましたが、40人には広すぎました。代わりに国際ラウンジは使えますか？50人ほど入ります。\n男：ラウンジの方がいいですね。今日の午後に予約します。次に食事ですが、昨年はピザを頼んだところ、宗教上の理由で食べられない学生が何人かいました。\n女：今年はビュッフェにして、全ての料理に表示を付け、ベジタリアンとハラールの選択肢も用意しましょう。1週間前なら食堂が対応できます。\n男：いいですね。では1日までに注文します。アクティビティは？昨年の日本についてのクイズは好評でした。\n女：クイズはまたやりましょう。ただ今回は混合チームにして、留学生が最初から日本人学生と話せるようにしましょう。\n男：名案です。もう1つ、短いスピーチを2人に頼みたいのですが、あなたが1人目になってくれますか？\n女：喜んで。もう1人は健二に頼みます。昨年留学していたので、新入生の気持ちが分かります。\n男：完璧です。まとめると、8日に国際ラウンジ、ビュッフェは1日までに注文、混合チームのクイズ、スピーチはあなたと健二。今夜メンバー全員に要約を送ります。","questions":[{"id":"L-2A-1-1","num":26,"question":"Why was the international lounge chosen over the student hall?","options":["It is closer to the dormitories","The student hall felt too large for the group","The lounge has a kitchen for the buffet","The student hall was already booked"],"answer":1,"evidence":"Last year we used the student hall, but it felt too big for forty people.","explanation":"昨年、学生ホールは40人に対して広すぎたと感じたため、より小さい国際ラウンジが選ばれた。","trapType":"理由の直接聞き取り"},{"id":"L-2A-1-2","num":27,"question":"What change will be made to the food this year?","options":["Pizza will be ordered from a different shop","A buffet with labeled dishes, including vegetarian and halal options","Students will bring their own food","The cafeteria will cook food at the party"],"answer":1,"evidence":"let's prepare a buffet with clear labels on every dish, including vegetarian and halal options","explanation":"昨年ピザが宗教上の理由で食べられない学生がいたため、今年は表示付きのビュッフェ（ベジタリアン・ハラール対応）に変更される。","trapType":"変更点の聞き取り"},{"id":"L-2A-1-3","num":28,"question":"Why will Kenji be asked to give a speech?","options":["He organized the party last year","He is the president of the exchange circle","He studied abroad last year","He knows all the new students"],"answer":2,"evidence":"he studied abroad last year, so he knows how the new students feel","explanation":"健二は昨年留学していたので新入生の気持ちが分かる、という理由でスピーチを頼まれる。","trapType":"理由の聞き取り"}]},{"setId":"L-2A-SET2","part":"2A","title":"Set 2: Returning the Wrong Textbook","situation":"学生が大学の書店で、間違えて買った教科書について話しています。","turns":[{"speaker":"M","text":"Excuse me, I bought this statistics textbook yesterday, but I think I got the wrong edition.","audio":"/teap/audio/s2-l-2a-set2-t1.mp3"},{"speaker":"W","text":"Let me check. This is the third edition. Which edition does your class use?","audio":"/teap/audio/s2-l-2a-set2-t2.mp3"},{"speaker":"M","text":"The syllabus says the fourth edition. I just grabbed the book from the shelf labeled 'Statistics' without checking.","audio":"/teap/audio/s2-l-2a-set2-t3.mp3"},{"speaker":"W","text":"I see. Normally we exchange textbooks within two weeks if they are unused. This one looks new — have you written in it?","audio":"/teap/audio/s2-l-2a-set2-t4.mp3"},{"speaker":"M","text":"No, I haven't even opened it. I noticed the cover was different when I compared it with my classmate's copy this morning.","audio":"/teap/audio/s2-l-2a-set2-t5.mp3"},{"speaker":"W","text":"Then we can exchange it. However, the fourth edition is 400 yen more expensive, so you'll need to pay the difference.","audio":"/teap/audio/s2-l-2a-set2-t6.mp3"},{"speaker":"M","text":"That's fine. Do you have the fourth edition in stock?","audio":"/teap/audio/s2-l-2a-set2-t7.mp3"},{"speaker":"W","text":"We're out of stock right now, but a new shipment arrives on Thursday. I can reserve a copy for you.","audio":"/teap/audio/s2-l-2a-set2-t8.mp3"},{"speaker":"M","text":"Please do. But my class meets on Wednesday — will I be OK without the book?","audio":"/teap/audio/s2-l-2a-set2-t9.mp3"},{"speaker":"W","text":"For this week, you can use the library's reference copy, which stays in the library. Many students do that while waiting.","audio":"/teap/audio/s2-l-2a-set2-t10.mp3"},{"speaker":"M","text":"That works. So I'll pay the 400 yen difference now, and pick up the fourth edition on Thursday?","audio":"/teap/audio/s2-l-2a-set2-t11.mp3"},{"speaker":"W","text":"Exactly. Here's your reservation slip. Please bring it with you on Thursday.","audio":"/teap/audio/s2-l-2a-set2-t12.mp3"}],"jaScript":"男：すみません、昨日この統計学の教科書を買ったのですが、版を間違えたようです。\n女：確認します。これは第3版ですね。授業では何版を使いますか？\n男：シラバスでは第4版です。「統計学」と書かれた棚から、確認せずに取ってしまいました。\n女：なるほど。通常、未使用なら2週間以内は交換できます。この本は新品のようですが、書き込みはしましたか？\n男：いいえ、開いてすらいません。今朝、クラスメートの本と比べて表紙が違うことに気づきました。\n女：では交換できます。ただし第4版は400円高いので、差額をお支払いいただきます。\n男：大丈夫です。第4版は在庫がありますか？\n女：今は在庫切れですが、木曜に新しい入荷があります。1冊お取り置きできます。\n男：お願いします。でも授業は水曜にあるんです。本なしで大丈夫でしょうか。\n女：今週は図書館の参考図書用のコピーが使えます。館内のみですが、待っている間そうする学生は多いです。\n男：それで大丈夫です。では今400円の差額を払って、木曜に第4版を受け取る、ですね？\n女：その通りです。こちらが取り置き票です。木曜にお持ちください。","questions":[{"id":"L-2A-2-1","num":29,"question":"Why can the man exchange the textbook?","options":["He bought it only yesterday","It is unused and within the exchange period","The shop made a mistake in labeling the shelf","His professor asked the shop to exchange it"],"answer":1,"evidence":"Normally we exchange textbooks within two weeks if they are unused.","explanation":"交換条件は「2週間以内・未使用」であり、本は開いてすらいないため交換可能。購入が昨日という点は条件そのものではない。","trapType":"条件の正確な聞き取り"},{"id":"L-2A-2-2","num":30,"question":"What problem does the man have with the exchange?","options":["The fourth edition is sold out everywhere","He cannot pay the 400 yen difference","The fourth edition will not arrive before his Wednesday class","The library does not have a reference copy"],"answer":2,"evidence":"a new shipment arrives on Thursday. I can reserve a copy for you.","explanation":"第4版の入荷は木曜だが、男性の授業は水曜にあるため、その時点では本が手元にないことが問題。図書館の参考本で今週はしのぐ。","trapType":"日程のずれに気づく型"},{"id":"L-2A-2-3","num":31,"question":"What will the man most likely do on Wednesday?","options":["Pick up the fourth edition","Use the reference copy in the library","Attend class without any book","Buy another copy at a different shop"],"answer":1,"evidence":"For this week, you can use the library's reference copy","explanation":"水曜の授業には図書館の参考図書用コピーを使うことになった。受け取りは木曜。","trapType":"曜日の取り違え"}]},{"setId":"L-2A-SET3","part":"2A","title":"Set 3: Discussing Survey Results with a Professor","situation":"学生が教授の研究室で、アンケート調査の結果について相談しています。","turns":[{"speaker":"W","text":"Professor, thank you for seeing me. I've finished collecting the survey data about students' part-time jobs, but I'm worried about one thing.","audio":"/teap/audio/s2-l-2a-set3-t1.mp3"},{"speaker":"M","text":"What concerns you?","audio":"/teap/audio/s2-l-2a-set3-t2.mp3"},{"speaker":"W","text":"We received 210 responses, but only 30 of them are from fourth-year students. Most responses came from first-years, because I handed out the survey near the first-year lecture rooms.","audio":"/teap/audio/s2-l-2a-set3-t3.mp3"},{"speaker":"M","text":"That is a sampling problem. If most respondents are first-years, your results will describe first-years, not the whole university. Can you collect more responses from senior students?","audio":"/teap/audio/s2-l-2a-set3-t4.mp3"},{"speaker":"W","text":"The seminar building has many fourth-year classes. I could hand out the survey there this week. How many more responses should I aim for?","audio":"/teap/audio/s2-l-2a-set3-t5.mp3"},{"speaker":"M","text":"Try to reach at least 80 fourth-year responses. Then the four years will be more balanced. What did the data show so far?","audio":"/teap/audio/s2-l-2a-set3-t6.mp3"},{"speaker":"W","text":"First-years work mostly at convenience stores and restaurants, and their main reason for working is daily expenses. But I expect the fourth-years will be different.","audio":"/teap/audio/s2-l-2a-set3-t7.mp3"},{"speaker":"M","text":"Probably. Many seniors work as tutors or office assistants, and they often save money for after graduation. Your final report should compare the years, not just describe the total.","audio":"/teap/audio/s2-l-2a-set3-t8.mp3"},{"speaker":"W","text":"I see. Then I'll collect the extra responses this week and rewrite the analysis plan to compare each year group separately.","audio":"/teap/audio/s2-l-2a-set3-t9.mp3"},{"speaker":"M","text":"Good. Bring me the updated results next Tuesday, and we will check the balance before you write the report.","audio":"/teap/audio/s2-l-2a-set3-t10.mp3"}],"jaScript":"女：先生、お時間ありがとうございます。学生のアルバイトに関するアンケートのデータ収集が終わったのですが、1つ心配な点があります。\n男：何が心配なのかな？\n女：回答は210件集まりましたが、4年生からの回答は30件だけです。1年生の講義室の近くで配ったので、回答の多くが1年生からになりました。\n男：それはサンプリングの問題だね。回答者の大半が1年生なら、結果は大学全体ではなく1年生を表すことになる。上級生からもっと回答を集められるかな？\n女：ゼミ棟には4年生の授業が多いので、今週そこで配れます。あと何件を目指すべきですか？\n男：4年生の回答を少なくとも80件にしよう。そうすれば4学年のバランスが取れる。今のところデータはどう出ている？\n女：1年生は主にコンビニや飲食店で働き、働く理由は日常の支出です。でも4年生は違うと思います。\n男：おそらくね。多くの上級生は家庭教師や事務補助として働き、卒業後のために貯金していることが多い。最終レポートでは、全体を述べるだけでなく学年を比較すべきだ。\n女：分かりました。では今週追加の回答を集めて、分析計画を学年ごとに比較する形に書き直します。\n男：いいね。来週の火曜に更新した結果を持ってきて。レポートを書く前にバランスを確認しよう。","questions":[{"id":"L-2A-3-1","num":32,"question":"What is the problem with the survey data?","options":["The total number of responses is too small","Most responses came from first-year students","Fourth-year students refused to answer","The questions were too difficult to understand"],"answer":1,"evidence":"We received 210 responses, but only 30 of them are from fourth-year students.","explanation":"総数210件は十分だが、回答が1年生に偏っているサンプリングの問題が指摘された。","trapType":"量ではなく偏りの問題"},{"id":"L-2A-3-2","num":33,"question":"What will the woman do this week?","options":["Rewrite the survey questions","Collect more responses from fourth-year students","Write the final report","Interview convenience store managers"],"answer":1,"evidence":"The seminar building has many fourth-year classes. I could hand out the survey there this week.","explanation":"今週はゼミ棟で4年生の回答を追加収集する（目標は少なくとも80件）。レポート作成はその後。","trapType":"次の行動の聞き取り"},{"id":"L-2A-3-3","num":34,"question":"What advice does the professor give for the final report?","options":["Focus only on first-year students","Compare the different year groups","Remove the fourth-year data","Add more questions about daily expenses"],"answer":1,"evidence":"Your final report should compare the years, not just describe the total.","explanation":"教授の助言は、全体の記述ではなく学年間の比較を行うこと。","trapType":"助言内容の聞き取り"}]},{"setId":"L-2B-SET1","part":"2B","title":"Set 1: Psychology — The Forgetting Curve","situation":"心理学の講義で、忘却曲線について聞いています。","turns":[{"speaker":"M","text":"Today we will look at one of the oldest experiments in psychology: Hermann Ebbinghaus's study of forgetting, published in 1885. Ebbinghaus wanted to measure how quickly we lose new information. To do this, he invented over two thousand nonsense syllables, such as 'DAX' and 'QEH,' which had no meaning at all. He memorized lists of them, and then tested himself after different periods of time to see how many he could still remember.","audio":"/teap/audio/s2-l-2b-set1-t1.mp3"},{"speaker":"M","text":"The result is the famous forgetting curve, shown in the chart. After only twenty minutes, he had already forgotten about forty percent of the list — just 58 percent remained. After one day, only about a third, 33 percent, was left. After two days it was 27 percent, and after six days, 25 percent. The key point is the shape: forgetting is fastest immediately after learning, and then it slows down.","audio":"/teap/audio/s2-l-2b-set1-t2.mp3"},{"speaker":"M","text":"Why does this happen? Ebbinghaus argued that new memories are fragile at first. Without review, the connections in the brain weaken quickly. However, each time we review the material, the memory becomes stronger and the forgetting curve becomes flatter. This is why reviewing on the second day is so effective: it catches the memory just before most of it disappears.","audio":"/teap/audio/s2-l-2b-set1-t3.mp3"},{"speaker":"M","text":"Modern research has largely confirmed his findings, although the exact numbers differ from person to person. Meaningful material is forgotten more slowly than nonsense syllables, and sleep improves memory significantly. Still, the basic pattern — rapid early loss, then slower decline — appears in almost every study. This is also the science behind spaced repetition software, which schedules reviews at increasing intervals.","audio":"/teap/audio/s2-l-2b-set1-t4.mp3"},{"speaker":"M","text":"For your own study, the lesson is practical. Reading your notes once is not enough. A short review within twenty-four hours, and another a few days later, will preserve far more than the same amount of time spent re-reading everything the night before an exam. In the next class, we will discuss how this connects to long-term memory. Please read chapter five before then.","audio":"/teap/audio/s2-l-2b-set1-t5.mp3"}],"stimulusChart":{"type":"line","title":"Memory Retention After Learning","sub":"Percentage of a list still remembered","unit":"%","max":100,"labels":["After 20 min","After 1 day","After 2 days","After 6 days"],"values":[58,33,27,25]},"jaScript":"男：今日は心理学で最も古い実験の1つ、1885年に発表されたエビングハウスの忘却の研究を見ます。エビングハウスは、新しい情報をどれだけ速く失うかを測りたいと考えました。そのために「DAX」「QEH」のような全く意味のない音節を2000以上作りました。そのリストを暗記し、時間を変えてテストし、どれだけ覚えているかを確認しました。\n結果が有名な忘却曲線で、グラフに示されています。わずか20分後にはリストの約40％をすでに忘れ、残りは58％だけでした。1日後には約3分の1、33％しか残りませんでした。2日後は27％、6日後は25％でした。要点は形です。忘却は学習直後が最も速く、その後ゆるやかになります。\nなぜこうなるのでしょうか。エビングハウスは、新しい記憶は最初はもろいと主張しました。復習しなければ、脳内のつながりは急速に弱まります。しかし復習するたびに記憶は強くなり、忘却曲線はなだらかになります。2日目の復習が効果的なのは、大半が消える直前に記憶を捉えるからです。\n現代の研究は彼の発見をほぼ裏付けていますが、正確な数値は人によって異なります。意味のある素材は無意味な音節より忘れにくく、睡眠は記憶を大きく改善します。それでも「最初に急速に失い、その後ゆるやかに減る」という基本パターンは、ほぼ全ての研究に現れます。これは、復習間隔を広げていく間隔反復ソフトの科学的根拠でもあります。\n皆さんの勉強への教訓は実践的です。ノートを1回読むだけでは不十分です。24時間以内の短い復習と、数日後のもう1回の復習は、試験前夜に全部読み直す同じ時間より、はるかに多くを保持します。次回はこれが長期記憶とどうつながるかを議論します。第5章を読んできてください。","questions":[{"id":"L-2B-1-1","num":35,"question":"Why did Ebbinghaus use nonsense syllables?","options":["They were easier to pronounce","They had no meaning, so memory could be measured purely","They were used in German schools","They could be learned faster than real words"],"answer":1,"evidence":"he invented over two thousand nonsense syllables, such as 'DAX' and 'QEH,' which had no meaning at all","explanation":"意味のない音節を使うことで、既存の知識に頼らない純粋な記憶の測定ができる。","trapType":"目的の聞き取り"},{"id":"L-2B-1-2","num":36,"question":"What is the main characteristic of the forgetting curve?","options":["Forgetting happens at a constant speed","Forgetting is fastest right after learning, then slows down","Most forgetting happens after six days","Forgetting stops completely after two days"],"answer":1,"evidence":"forgetting is fastest immediately after learning, and then it slows down","explanation":"曲線の要点は、学習直後の喪失が最も速く、その後はゆるやかになること。","trapType":"要点の言い換え"},{"id":"L-2B-1-3","num":37,"question":"According to the chart, what percentage of the list remained after one day?","options":["58 percent","27 percent","33 percent","25 percent"],"answer":2,"evidence":"After one day, only about a third, 33 percent, was left.","explanation":"グラフと本文の両方で、1日後の保持率は33％。58％は20分後の値。","trapType":"グラフ読み取り"},{"id":"L-2B-1-4","num":38,"question":"What study advice does the lecturer give?","options":["Read all your notes the night before the exam","Review within twenty-four hours and again a few days later","Study only meaningful material","Sleep instead of reviewing"],"answer":1,"evidence":"A short review within twenty-four hours, and another a few days later, will preserve far more","explanation":"24時間以内の復習＋数日後の復習が、前夜の読み直しより効果的だと述べている。","trapType":"助言の聞き取り"}]},{"setId":"L-2B-SET2","part":"2B","title":"Set 2: Earth Science — Volcanoes and Moving Plates","situation":"地球科学の講義で、火山とプレートの動きについて聞いています。","turns":[{"speaker":"W","text":"In this lecture, we will examine why volcanoes appear in some parts of the world but not others. If you look at a world map of volcanoes, you will notice they are not spread evenly. Instead, they form lines and belts, especially around the edges of the Pacific Ocean — the so-called Ring of Fire. This pattern was a mystery until the theory of plate tectonics explained it in the 1960s.","audio":"/teap/audio/s2-l-2b-set2-t1.mp3"},{"speaker":"W","text":"According to the theory, the Earth's surface is divided into huge plates that move very slowly, only a few centimeters a year. Where two plates move toward each other, one plate may slide beneath the other. As the lower plate sinks, it heats up and partly melts, and the melted rock rises to the surface as magma. When that magma breaks through, a volcano is born. This process explains the volcanoes of Japan and the west coast of South America.","audio":"/teap/audio/s2-l-2b-set2-t2.mp3"},{"speaker":"W","text":"Volcanoes can also form where plates move apart. In the middle of the Atlantic Ocean, two plates are separating, and magma rises to fill the gap, building an underwater mountain range. Iceland sits directly on this boundary, which is why it has so many volcanoes despite its northern location. A third type, called a hotspot, forms above a rising column of hot material from deep inside the Earth; Hawaii is the best-known example.","audio":"/teap/audio/s2-l-2b-set2-t3.mp3"},{"speaker":"W","text":"Understanding these mechanisms is not just academic. About five hundred million people live within reach of an active volcano. Scientists therefore monitor volcanoes closely, measuring small earthquakes and changes in the shape of the ground. These signs often appear weeks before an eruption, allowing warnings to be issued. The 1991 eruption of Mount Pinatubo in the Philippines was predicted successfully, and tens of thousands of people were evacuated in time.","audio":"/teap/audio/s2-l-2b-set2-t4.mp3"},{"speaker":"W","text":"To summarize: volcanoes form mainly where plates collide, where they separate, and above hotspots. Their distribution on the map is therefore a direct picture of the moving plates below. Next week, we will turn to earthquakes, which occur along the same boundaries. For homework, label the plate boundaries on the map in your handout and mark where each of the three volcano types is found.","audio":"/teap/audio/s2-l-2b-set2-t5.mp3"}],"jaScript":"女：この講義では、なぜ火山が世界の特定の場所に現れ、他の場所には現れないのかを検討します。火山の世界地図を見ると、均等に分布していないことが分かります。代わりに、特に太平洋の縁辺、いわゆる環太平洋火山帯に沿って、線や帯を形作っています。このパターンは、1960年代にプレートテクトニクス理論が説明するまで謎でした。\n理論によれば、地表は巨大なプレートに分かれ、年に数センチという速さでゆっくり動いています。2つのプレートが近づく場所では、一方が他方の下に滑り込みます。下のプレートが沈むと熱せられて部分的に溶け、溶けた岩石がマグマとして地表へ上昇します。そのマグマが噴出すると火山が生まれます。このプロセスが、日本や南米西海岸の火山を説明します。\n火山はプレートが離れる場所にもできます。大西洋の中央では2つのプレートが離れていて、マグマが上昇して隙間を埋め、海底山脈を作っています。アイスランドはちょうどこの境界の上にあり、北に位置するのに火山が多いのはそのためです。第3のタイプはホットスポットと呼ばれ、地球深部から上昇する熱い物質の柱の上にできます。ハワイが最も有名な例です。\nこれらの仕組みの理解は学問だけのためではありません。約5億人が活火山の影響圏内に住んでいます。そのため科学者は火山を注意深く監視し、小さな地震や地表の形の変化を測定します。こうした兆候は噴火の数週間前に現れることが多く、警報を出すことができます。1991年のフィリピン・ピナトゥボ山の噴火は予測が成功し、何万人もが間に合うように避難しました。\nまとめると、火山は主にプレートが衝突する場所、離れる場所、そしてホットスポットの上にできます。地図上の分布は、その下で動くプレートの姿を直接映したものです。来週は、同じ境界で発生する地震を取り上げます。宿題として、配布資料の地図にプレート境界を書き入れ、3タイプの火山がどこにあるか印を付けてください。","questions":[{"id":"L-2B-2-1","num":39,"question":"What pattern do volcanoes show on a world map?","options":["They are spread evenly across the continents","They form belts, especially around the Pacific edges","They appear only near the equator","They are found only on islands"],"answer":1,"evidence":"they form lines and belts, especially around the edges of the Pacific Ocean","explanation":"火山は均等ではなく、太平洋の縁辺などに帯状に分布する（環太平洋火山帯）。","trapType":"分布パターンの聞き取り"},{"id":"L-2B-2-2","num":40,"question":"Why does Iceland have many volcanoes?","options":["It sits above a hotspot","It is close to Japan","It sits on a boundary where plates are separating","Its rocks melt easily in cold climates"],"answer":2,"evidence":"Iceland sits directly on this boundary, which is why it has so many volcanoes","explanation":"アイスランドはプレートが離れる境界の上に位置するため火山が多い。ホットスポットの例はハワイ。","trapType":"例の対応関係"},{"id":"L-2B-2-3","num":41,"question":"How do scientists know an eruption may be coming?","options":["They watch for changes in animal behavior","They measure small earthquakes and changes in the ground shape","They check the color of the sky","They count the number of visitors"],"answer":1,"evidence":"measuring small earthquakes and changes in the shape of the ground. These signs often appear weeks before an eruption","explanation":"小さな地震と地表の形状変化が噴火の前兆として観測される。","trapType":"具体例の聞き取り"},{"id":"L-2B-2-4","num":42,"question":"What will the class study next week?","options":["Hotspots","The Ring of Fire","Earthquakes","Underwater mountains"],"answer":2,"evidence":"Next week, we will turn to earthquakes, which occur along the same boundaries.","explanation":"来週のテーマは、同じプレート境界で起きる地震。","trapType":"次回予告の聞き取り"}]},{"setId":"L-2B-SET3","part":"2B","title":"Set 3: Economics — Inflation and the Price of Things","situation":"経済学の講義で、インフレーションについて聞いています。","turns":[{"speaker":"M","text":"Today we will discuss inflation — the general rise in prices over time. To make this concrete, look at the chart showing the price of a cinema ticket in Japan. In 1960, a ticket cost about 180 yen. By 1980 it had reached 1,100 yen, by 2000 it was 1,700 yen, and in 2020 it stood at about 1,900 yen. The ticket itself barely changed; what changed was the value of money.","audio":"/teap/audio/s2-l-2b-set3-t1.mp3"},{"speaker":"M","text":"Economists measure inflation using a price index, which tracks the cost of a fixed basket of goods and services. When the index rises by three percent in a year, we say the inflation rate is three percent. A small amount of inflation is considered normal, and even healthy, because it encourages people to spend and invest rather than hold cash that loses value.","audio":"/teap/audio/s2-l-2b-set3-t2.mp3"},{"speaker":"M","text":"Problems begin when inflation becomes too fast or unpredictable. If prices rise quickly, people cannot plan, and savings lose value rapidly. Workers demand higher wages, companies raise prices again to cover the higher wages, and a damaging cycle can begin. This is one reason central banks set a target — in Japan, the target is two percent — and adjust interest rates to stay near it.","audio":"/teap/audio/s2-l-2b-set3-t3.mp3"},{"speaker":"M","text":"The opposite problem, deflation, can be equally harmful. When prices fall year after year, consumers delay purchases, expecting things to become cheaper. Companies then earn less, cut wages, and prices fall further. Japan experienced long periods of mild deflation from the late 1990s, which is why its central bank worked for many years to push inflation up to the target, not down.","audio":"/teap/audio/s2-l-2b-set3-t4.mp3"},{"speaker":"M","text":"So, inflation is neither good nor bad in itself; its speed and predictability matter. Next time, we will examine how interest rates are used to control it. Before the next class, find one item whose price you know well — a train fare, a snack, anything — and check how its price has changed over the past twenty years. Bring your example to class.","audio":"/teap/audio/s2-l-2b-set3-t5.mp3"}],"stimulusChart":{"type":"bar","title":"Price of a Cinema Ticket in Japan","sub":"Average price per ticket","unit":"yen","max":2000,"items":[{"label":"1960","value":180},{"label":"1980","value":1100},{"label":"2000","value":1700},{"label":"2020","value":1900}]},"jaScript":"男：今日はインフレーション、つまり時間とともに価格が全般的に上昇することについて議論します。具体的にするため、日本の映画チケットの価格のグラフを見てください。1960年、チケットは約180円でした。1980年には1,100円、2000年には1,700円になり、2020年には約1,900円でした。チケット自体はほとんど変わっていません。変わったのはお金の価値です。\n経済学者は、固定された商品とサービスのバスケットの価格を追う物価指数でインフレを測ります。指数が1年で3％上がれば、インフレ率は3％と言います。少量のインフレは正常で、むしろ健全だと考えられます。価値が下がる現金を抱えるより、支出や投資を促すからです。\n問題は、インフレが速すぎたり予測できなくなったりしたときに始まります。価格が急上昇すれば、人々は計画を立てられず、貯蓄は急速に価値を失います。労働者は賃上げを求め、企業はその賃金をまかなうために再び価格を上げ、悪循環が始まりかねません。中央銀行が目標（日本では2％）を設定し、それに近づくよう金利を調整する理由の1つです。\n逆の問題であるデフレも同じくらい有害です。価格が年々下がれば、消費者は「もっと安くなる」と購入を先延ばしします。企業は収益が減り、賃金を削り、価格はさらに下がります。日本は1990年代後半から長期間、緩やかなデフレを経験しました。そのため中央銀行は長年、インフレを下げるのではなく目標まで引き上げようと努めてきました。\nつまりインフレ自体は良い悪いのではなく、速度と予測可能性が重要なのです。次回は、金利がインフレの制御にどう使われるかを検討します。次回までに、電車賃でもお菓子でも、価格をよく知っているものを1つ選び、過去20年でどう変わったか調べてください。例を授業に持ってきてください。","questions":[{"id":"L-2B-3-1","num":43,"question":"According to the chart, what was the price of a cinema ticket in 2000?","options":["180 yen","1,100 yen","1,700 yen","1,900 yen"],"answer":2,"evidence":"by 2000 it was 1,700 yen","explanation":"グラフと本文の両方で、2000年は1,700円。","trapType":"グラフ読み取り"},{"id":"L-2B-3-2","num":44,"question":"Why is a small amount of inflation considered healthy?","options":["It makes savings grow faster","It encourages spending and investment","It keeps prices exactly the same","It allows companies to cut wages"],"answer":1,"evidence":"it encourages people to spend and invest rather than hold cash that loses value","explanation":"少量のインフレは、価値が下がる現金の保有より支出・投資を促すため健全とされる。","trapType":"理由の聞き取り"},{"id":"L-2B-3-3","num":45,"question":"What cycle can develop when inflation is too fast?","options":["Prices fall and wages rise","Higher wages lead to higher prices, which lead to higher wages again","Consumers save more and companies invest more","Interest rates fall and prices stabilize"],"answer":1,"evidence":"Workers demand higher wages, companies raise prices again to cover the higher wages, and a damaging cycle can begin.","explanation":"賃上げ→価格上昇→さらなる賃上げという悪循環が説明されている。","trapType":"プロセスの聞き取り"},{"id":"L-2B-3-4","num":46,"question":"Why can deflation be harmful?","options":["Consumers buy too much too quickly","Consumers delay purchases, so companies earn less and cut wages","Prices rise faster than wages","Central banks lose their targets"],"answer":1,"evidence":"When prices fall year after year, consumers delay purchases, expecting things to become cheaper. Companies then earn less, cut wages","explanation":"デフレでは購入の先延ばし→企業の収益減→賃金カット→さらなる価格下落が起きる。","trapType":"因果関係の聞き取り"}]},{"setId":"L-2B-SET4","part":"2B","title":"Set 4: Art History — Ukiyo-e and European Painters","situation":"美術史の講義で、浮世絵とヨーロッパの画家について聞いています。","turns":[{"speaker":"W","text":"In the second half of the nineteenth century, something surprising happened in European art. After Japan opened its ports to foreign trade in the 1850s, Japanese goods began arriving in Europe in large quantities. Among them were ukiyo-e — colorful woodblock prints by artists such as Hokusai and Hiroshige. European painters who saw these prints were struck by features they had never seen in Western art.","audio":"/teap/audio/s2-l-2b-set4-t1.mp3"},{"speaker":"W","text":"What impressed them most? First, the compositions: ukiyo-e often cut off objects at the edge of the picture and placed the main subject far from the center. Second, the flat areas of bright color, without the gradual shading that European painting had used for centuries. And third, the subjects themselves — everyday scenes, actors, and landscapes rather than kings and religious stories. For young European artists searching for a new style, these prints were a revelation.","audio":"/teap/audio/s2-l-2b-set4-t2.mp3"},{"speaker":"W","text":"The influence is easy to see in famous works. Van Gogh copied two of Hiroshige's prints in oil paint, even adding Japanese characters around the borders. Monet collected over two hundred Japanese prints and decorated his house with them; his paintings of his garden show similar compositions. Toulouse-Lautrec designed posters with flat color and bold outlines that clearly came from ukiyo-e. This movement of influence is often called Japonisme.","audio":"/teap/audio/s2-l-2b-set4-t3.mp3"},{"speaker":"W","text":"Ironically, at the very time Europeans were celebrating ukiyo-e, many Japanese considered the prints cheap, everyday products — they were even used as wrapping paper for exported ceramics. Thousands of prints left Japan and survived in European collections, while in Japan they were often thrown away. Today, museums in Boston and Amsterdam hold some of the finest collections in the world.","audio":"/teap/audio/s2-l-2b-set4-t4.mp3"},{"speaker":"W","text":"The lesson of this story is that artistic value is not fixed. A print that was wrapping paper in one country became a masterpiece in another, and it changed the direction of European painting. Next week, we will look at the reverse flow: how Western techniques entered Japanese painting during the Meiji period. Please look at the images in chapter eight before the class.","audio":"/teap/audio/s2-l-2b-set4-t5.mp3"}],"jaScript":"女：19世紀後半、ヨーロッパの美術に驚くべきことが起きました。1850年代に日本が外国貿易に港を開いた後、日本の品々が大量にヨーロッパに届き始めました。その中には、北斎や広重といった画家による色鮮やかな木版画、浮世絵がありました。これらの版画を見たヨーロッパの画家たちは、西洋美術にはなかった特徴に心を打たれました。\n何が最も印象的だったのでしょうか。第一に構図です。浮世絵はしばしば画面の端で対象を切り取り、主題を中央から遠くに置きます。第二に、ヨーロッパ絵画が何世紀も使ってきた段階的な陰影のない、明るい色の平らな面。第三に主題そのもので、王や宗教物語ではなく、日常の情景、役者、風景でした。新しい様式を求める若いヨーロッパの芸術家にとって、これらの版画は啓示でした。\nその影響は有名な作品にはっきり見えます。ゴッホは広重の版画2点を油絵で模写し、周りに漢字まで描き加えました。モネは200点以上の日本の版画を集めて家を飾り、彼の庭の絵には似た構図が見えます。トゥールーズ＝ロートレックは、浮世絵由来であることが明らかな平らな色と大胆な輪郭でポスターをデザインしました。この影響の流れはしばしばジャポニスムと呼ばれます。\n皮肉なことに、ヨーロッパ人が浮世絵を称賛していたまさにその頃、多くの日本人は版画を安い日常品と考え、輸出陶磁器の包装紙にさえ使っていました。何千点もの版画が日本を離れてヨーロッパのコレクションに残りましたが、日本ではしばしば捨てられました。今日、ボストンやアムステルダムの美術館が世界屈指のコレクションを所蔵しています。\nこの話の教訓は、芸術的価値は固定されていないということです。ある国では包装紙だった版画が、別の国では名作となり、ヨーロッパ絵画の方向を変えました。来週は逆の流れ、明治期に西洋の技法が日本の絵画に入ってきた過程を見ます。第8章の画像を授業前に見ておいてください。","questions":[{"id":"L-2B-4-1","num":47,"question":"What first brought large numbers of ukiyo-e prints to Europe?","options":["A European art exhibition in Tokyo","Japan opening its ports to foreign trade","Japanese artists moving to Paris","A gift from the Japanese government"],"answer":1,"evidence":"After Japan opened its ports to foreign trade in the 1850s, Japanese goods began arriving in Europe in large quantities.","explanation":"1850年代の開港と貿易開始が、浮世絵を含む日本品の大量流入のきっかけ。","trapType":"きっかけの聞き取り"},{"id":"L-2B-4-2","num":48,"question":"Which feature of ukiyo-e impressed European painters?","options":["Detailed shading of faces","Subjects placed away from the center of the picture","Huge canvas sizes","Religious themes"],"answer":1,"evidence":"ukiyo-e often cut off objects at the edge of the picture and placed the main subject far from the center","explanation":"主題を中央から外す構図、平らな色面、日常の主題が印象を与えた。陰影は逆に「ない」ことが特徴。","trapType":"特徴の聞き取り"},{"id":"L-2B-4-3","num":49,"question":"What did Van Gogh do with Hiroshige's prints?","options":["He bought over two hundred of them","He designed posters based on them","He copied two of them in oil paint","He used them as wrapping paper"],"answer":2,"evidence":"Van Gogh copied two of Hiroshige's prints in oil paint","explanation":"ゴッホは広重の2点を油絵で模写。200点以上集めたのはモネ、ポスターはロートレック。","trapType":"人物と行動の対応"},{"id":"L-2B-4-4","num":50,"question":"What is ironic about the history of ukiyo-e?","options":["Europeans paid very little for the prints","In Japan the prints were treated as cheap everyday items while Europe treasured them","Japanese artists copied European paintings first","The prints were made in Europe, not Japan"],"answer":1,"evidence":"many Japanese considered the prints cheap, everyday products — they were even used as wrapping paper","explanation":"ヨーロッパで称賛される一方、日本では安い日常品として包装紙にまで使われていた点が皮肉として語られている。","trapType":"講義の要点（皮肉）の聞き取り"}]}]};
